/* long-press / swipe on the collapsed control */
function gesture(el, expandOnTap){
  /* タップ＝click（確実に飛ぶ）／長押し・スワイプ＝ポインタで検出して直後の click を無視する */
  var timer = null, sx = 0, sy = 0, suppress = false;
  function stop(){ if(timer){ clearTimeout(timer); timer = null; } }
  el.addEventListener("pointerdown", function(e){
    sx = e.clientX; sy = e.clientY; suppress = false;
    stop();
    timer = setTimeout(function(){ timer = null; suppress = true; setExpanded(true); }, 420);
  });
  el.addEventListener("pointermove", function(e){
    if(!timer) return;
    if(Math.abs(e.clientX - sx) > 14 || Math.abs(e.clientY - sy) > 14){
      stop(); suppress = true; setExpanded(true);
    }
  });
  el.addEventListener("pointerup", stop);
  el.addEventListener("pointercancel", stop);
  el.addEventListener("click", function(e){
    e.stopPropagation();
    if(suppress){ suppress = false; return; }
    togglePlay();
    if(expandOnTap){ upVel = 1.2; setExpanded(true); }   /* 再生/一時停止でも出し直す */
  });
}
gesture($("#plA"), true); gesture($("#miniC"), true);

