/* scroll: collapse expanded control + refresh jump buttons */
/* コントロールの出し入れはスクロールの向きで決める。
   下へスクロール（先を読み進める）= 隠す / 上へスクロール（前を見返す）= 出す。
   再生・一時停止のタップでも出す（gesture の expandOnTap）。 */
var SWIPE = 12;         /* この px 数だけ同じ向きに動いたら確定（細かい揺れで切り替わらないように） */
/* スクロールで進捗バーを出すのは書き起こしタブだけ（上スクロール＝前を見返す動作、
   および一番下まで到達）。他の3タブは再生・一時停止のタップでだけ出る。
   下端付近で上へ払うと出す仕組みは、跳ね返りでも出てしまうため取りやめ。 */
var lastTop = 0, lastTime = 0, dir = 0, acc = 0, quietUntil = 0;
function quietScroll(){ quietUntil = Date.now() + 700; }
$("#scroller").addEventListener("scroll", function(){
  var sc = $("#scroller");
  var t = sc.scrollTop, now = Date.now();
  var dy = t - lastTop, dt = now - lastTime;
  lastTop = t; lastTime = now;
  S.scrollMem[S.tab] = t;
  var atTop = t <= 1;
  var atBottom = t >= sc.scrollHeight - sc.clientHeight - 1;
  if(now > quietUntil){
    if(atTop){
      /* 一番上まで来た時の跳ね返り（下向きに戻る動き）で畳まないようにする */
      dir = 0; acc = 0;
    } else if(atBottom && S.variant === "C" && S.tab === "transcript"){
      /* 一番下まで来たら出す（C案のみ）。突然出ないようゆっくり馴染ませる。
         既に出ている時は触らない（cSoft を持ち越して次の展開を遅くしないため） */
      if(!S.expanded){ upVel = 0.6; cSoft = true; setExpanded(true); }
    } else if(dy !== 0){
      var d = dy > 0 ? 1 : -1;
      if(d !== dir){ dir = d; acc = 0; }      /* 向きが変わったら積算をやり直す */
      acc += Math.abs(dy);
      if(acc >= SWIPE){
        if(d > 0) setExpanded(false);                    /* 下へ = 読み進める → 畳む */
        else if(S.tab === "transcript"){
          if(dt > 0) upVel = Math.abs(dy) / dt;          /* 上スクロールの速さを反映させる */
          setExpanded(true);
        }
      }
    }
  }
  updateJump();
  syncChips();
}, {passive:true});
/* 指やホイールで触った時点で自前スクロールは譲り、自動追従も止める */
function userTouch(){ userAt = Date.now(); stopSmooth(); }
["touchstart","touchmove","wheel","pointerdown"].forEach(function(ev){
  $("#scroller").addEventListener(ev, userTouch, {passive:true});
});

