/* ---------- 検索 ---------- */
var SE = {on:false, q:"", hits:[], at:0};   /* hits = [{line, start}] */

function seFind(){
  SE.hits = [];
  var q = SE.q;
  if(!q) return;
  var lq = q.toLowerCase();
  LINES.forEach(function(l){
    var t = l.text.toLowerCase(), from = 0, k;
    while((k = t.indexOf(lq, from)) >= 0){ SE.hits.push({line:l.i, start:k}); from = k + lq.length; }
  });
  if(SE.at >= SE.hits.length) SE.at = 0;
}
/* 一致した箇所を印で囲む。今いる一致だけ色を変える */
function sePaint(){
  var q = SE.q, lq = q.toLowerCase();
  var cur = SE.hits[SE.at];
  $$("#panelTranscript .bb").forEach(function(el){
    var i = +el.getAttribute("data-line"), text = LINES[i].text;
    if(!q){ el.innerHTML = esc(text); return; }
    var lt = text.toLowerCase(), out = "", from = 0, k, seen = 0;
    while((k = lt.indexOf(lq, from)) >= 0){
      var isNow = cur && cur.line === i && cur.start === k;
      out += esc(text.slice(from, k))
           + '<mark class="hit' + (isNow ? " now" : "") + '">' + esc(text.substr(k, q.length)) + '</mark>';
      from = k + q.length; seen++;
    }
    out += esc(text.slice(from));
    el.innerHTML = seen ? out : esc(text);
  });
  markCurrent();
}
function sePaintCount(){
  $("#seCount").textContent = SE.hits.length ? (SE.at + 1) + "/" + SE.hits.length : (SE.q ? "0/0" : "");
  $("#seClear").hidden = !SE.q;
  var none = !SE.hits.length;
  $("#searchNav").hidden = !SE.on || none;
  $("#sePrev").disabled = none; $("#seNext").disabled = none;
}
function seGo(d){
  if(!SE.hits.length) return;
  SE.at = (SE.at + d + SE.hits.length) % SE.hits.length;
  sePaint(); sePaintCount(); seScroll();
}
/* 今いる一致を帯の真ん中あたりへ */
function seScroll(){
  var h = SE.hits[SE.at]; if(!h) return;
  var el = $('#panelTranscript .bb[data-line="'+h.line+'"]'); if(!el) return;
  var sc = $("#scroller");
  var pr = phone.getBoundingClientRect(), k = pr.width / 430;
  var r = el.getBoundingClientRect();
  var elTop = (r.top - pr.top) / k, elH = r.height / k;
  var visTop = 135, visBottom = 762;
  var want = visTop + Math.max(12, (visBottom - visTop - elH) / 2);
  var max = Math.max(0, sc.scrollHeight - sc.clientHeight);
  quietScroll();
  sc.scrollTop = Math.max(0, Math.min(sc.scrollTop + (elTop - want), max));
}
function openSearch(){
  SE.on = true; SE.q = ""; SE.hits = []; SE.at = 0;
  setTab("transcript");
  phone.classList.add("searching");
  $("#searchBar").hidden = false;
  $("#seInput").value = "";
  sePaint(); sePaintCount();
  $("#scroller").scrollTop = 0;
  setTimeout(function(){ $("#seInput").focus(); }, 80);
}
function closeSearch(){
  SE.on = false; SE.q = ""; SE.hits = []; SE.at = 0;
  phone.classList.remove("searching");
  $("#searchBar").hidden = true;
  $("#searchNav").hidden = true;
  sePaint();
}
$("#searchBtn").addEventListener("click", function(e){ e.stopPropagation(); openSearch(); });
$("#seCancel").addEventListener("click", closeSearch);
$("#seClear").addEventListener("click", function(){
  $("#seInput").value = ""; SE.q = ""; seFind(); sePaint(); sePaintCount(); $("#seInput").focus();
});
$("#seInput").addEventListener("input", function(){
  SE.q = $("#seInput").value.trim(); SE.at = 0;
  seFind(); sePaint(); sePaintCount();
  if(SE.hits.length) seScroll();
});
$("#sePrev").addEventListener("click", function(){ seGo(-1); });
$("#seNext").addEventListener("click", function(){ seGo(1); });

